CREATE OR REPLACE FUNCTION public.cancel_letter_workflow(p_actor uuid, p_letter uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l letters; t letter_types; r cancellation_requests; head uuid; basis text; needed integer; target uuid; done_count integer;
begin
 select * into l from letters where id=p_letter for update;
 if l.id is null or (app.active_assignment(p_actor)).id is null then raise exception 'Akun/surat tidak valid.'; end if;
 if p_action='CANCEL_DRAFT' then
   if l.creator_id<>p_actor or l.status not in ('DRAFT','REVISION_REQUESTED') then raise exception 'Hanya pembuat dapat membatalkan draft yang dapat diedit.'; end if;
   if nullif(trim(p_reason),'') is null then raise exception 'Alasan pembatalan wajib.'; end if;
   update letters set status='CANCELLED',status_reason=p_reason where id=l.id;
   insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,status_before,status_after,reason) values(p_actor,l.id,'CANCEL_DRAFT','letters',l.id::text,l.status,'CANCELLED',p_reason);
   return 'CANCELLED';
 end if;
 if l.status<>'NUMBERED' then raise exception 'Surat belum bernomor atau sudah dibatalkan.'; end if;
 select * into t from letter_types where id=l.letter_type_id;
 select * into r from cancellation_requests where letter_id=l.id and status='PENDING' order by created_at desc limit 1 for update;
 if p_action='REQUEST' then
   if l.creator_id<>p_actor then raise exception 'Hanya pembuat dapat mengajukan pembatalan.'; end if;
   if r.id is not null then return 'PENDING'; end if;
   if nullif(trim(p_reason),'') is null then raise exception 'Alasan pembatalan wajib.'; end if;
   insert into cancellation_requests(letter_id,requested_by,reason,status) values(l.id,p_actor,p_reason,'PENDING') returning * into r;
   if t.category='INTERNAL' then
     select a.profile_id into head from organizational_units u join user_assignments a on a.id=u.head_assignment_id where u.id=l.creator_unit_id and a.is_active;
     if head is null then raise exception 'Kepala unit belum ditetapkan untuk otorisasi pembatalan.'; end if;
     insert into cancellation_authorizations(request_id,authorizer_id,authority_basis) values(r.id,head,'UNIT_HEAD');
     insert into cancellation_authorizations(request_id,authorizer_id,authority_basis,delegation_id)
     select r.id,a.profile_id,'DESIGNATED_OFFICIAL',d.id from authority_delegations d join user_assignments a on a.id=d.grantee_assignment_id join organizational_units u on u.head_assignment_id=d.grantor_assignment_id
     where d.scope_unit_id=l.creator_unit_id and u.id=l.creator_unit_id and d.is_active and a.is_active and d.authority_type='LETTER_CANCELLATION' and (d.valid_from is null or d.valid_from<=(now() at time zone 'Asia/Jakarta')::date) and (d.valid_until is null or d.valid_until>=(now() at time zone 'Asia/Jakarta')::date) and a.profile_id<>head;
   else
     if cardinality(l.signer_ids)<>(case when t.category='BILLING' then 2 else 1 end) then raise exception 'Penandatangan surat lama belum lengkap untuk otorisasi.'; end if;
     insert into cancellation_authorizations(request_id,authorizer_id,authority_basis)
     select r.id,s,case when t.category='BILLING' then case when ord=1 then 'SM_FINANCE' else 'DIRECTOR' end else 'SIGNING_OFFICIAL' end from unnest(l.signer_ids) with ordinality a(s,ord);
   end if;
   insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,reason) values(p_actor,l.id,'CANCELLATION_REQUESTED','cancellation_requests',r.id::text,p_reason);
   return 'PENDING';
 end if;
 if r.id is null or coalesce(p_action,'') not in ('APPROVE','DECLINE') then raise exception 'Permohonan pembatalan tidak aktif.'; end if;
 if not exists(select 1 from cancellation_authorizations where request_id=r.id and authorizer_id=p_actor and decision is null) then raise exception 'Akun ini bukan pemegang otorisasi pembatalan.'; end if;
 if t.category='INTERNAL' then
   if not exists(select 1 from cancellation_authorizations ca left join authority_delegations d on d.id=ca.delegation_id where ca.request_id=r.id and ca.authorizer_id=p_actor and ((ca.authority_basis='UNIT_HEAD' and exists(select 1 from organizational_units u join user_assignments a on a.id=u.head_assignment_id where u.id=l.creator_unit_id and a.profile_id=p_actor and a.is_active)) or (ca.authority_basis='DESIGNATED_OFFICIAL' and d.scope_unit_id=l.creator_unit_id and d.grantor_assignment_id=(select head_assignment_id from organizational_units where id=l.creator_unit_id) and exists(select 1 from user_assignments a where a.id=d.grantee_assignment_id and a.profile_id=p_actor and a.is_active) and d.is_active and (d.valid_from is null or d.valid_from<=(now() at time zone 'Asia/Jakarta')::date) and (d.valid_until is null or d.valid_until>=(now() at time zone 'Asia/Jakarta')::date)))) then raise exception 'Kewenangan pembatalan sudah tidak aktif.'; end if;
 elsif not app.valid_signer(p_actor) then raise exception 'Pejabat penandatangan sudah tidak aktif.'; end if;
 if p_action='DECLINE' and nullif(trim(p_reason),'') is null then raise exception 'Alasan penolakan wajib.'; end if;
 update cancellation_authorizations set decision=case when p_action='APPROVE' then 'APPROVED' else 'DECLINED' end,note=p_reason,decided_at=now() where request_id=r.id and authorizer_id=p_actor and decision is null;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,reason) values(p_actor,l.id,'CANCELLATION_'||p_action,'cancellation_requests',r.id::text,p_reason);
 if p_action='DECLINE' then update cancellation_requests set status='DECLINED' where id=r.id; return 'DECLINED'; end if;
 needed:=case when t.category='BILLING' then 2 else 1 end;
 select count(distinct authorizer_id) into done_count from cancellation_authorizations where request_id=r.id and decision='APPROVED';
 if done_count>=needed then
   perform cancel_numbered_letter(l.id,p_actor,r.reason);
   update cancellation_requests set status='EXECUTED',executed_at=now() where id=r.id;
   update signature_requests set status='CANCELLED' where letter_id=l.id and status in ('PENDING','WAITING');
   return 'EXECUTED';
 end if;
 return 'PENDING';
end $function$

CREATE OR REPLACE FUNCTION public.cancel_numbered_letter(p_letter_id uuid, p_actor uuid, p_reason text)
 RETURNS letters
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_letter letters;
begin
  if coalesce(trim(p_reason), '') = '' then raise exception 'REASON_REQUIRED' using errcode = 'P0001'; end if;
  select * into v_letter from letters where id = p_letter_id for update;
  if v_letter.status <> 'NUMBERED' then raise exception 'LETTER_NOT_NUMBERED' using errcode = 'P0001'; end if;
  update number_issuances set status = 'CANCELLED' where letter_id = p_letter_id;
  update letters set status = 'CANCELLED', status_reason = p_reason where id = p_letter_id returning * into v_letter;
  insert into audit_logs (actor_id, letter_id, action, entity_type, entity_id, status_before, status_after, official_number, reason)
  values (p_actor, p_letter_id, 'LETTER_CANCELLED', 'letters', p_letter_id::text, 'NUMBERED', 'CANCELLED', v_letter.official_number, p_reason);
  return v_letter;
end $function$

CREATE OR REPLACE FUNCTION public.check_disposition_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if new.status in ('IN_REVIEW','DONE') and new.requires_letter then
   if not exists(select 1 from letters l where l.id=new.response_letter_id and l.creator_id=new.recipient_id and l.status='NUMBERED' and l.finalized_at is not null) then
     raise exception 'Selesaikan surat tindak lanjut beserta pengesahannya sebelum mengirim hasil.';
   end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.complete_number_issuance(p_issuance_id uuid, p_version_id uuid, p_actor uuid)
 RETURNS letters
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_iss number_issuances;
  v_letter letters;
begin
  select * into v_iss from number_issuances where id = p_issuance_id;
  if not found then raise exception 'ISSUANCE_NOT_FOUND' using errcode = 'P0002'; end if;
  select * into v_letter from letters where id = v_iss.letter_id;
  return v_letter;
end $function$

CREATE OR REPLACE FUNCTION public.disposition_workflow(p_actor uuid, p_action text, p_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT NULL::integer, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare d dispositions; a user_assignments; r user_assignments; lvl integer; rlv integer; target uuid; old_status text; src uuid;
begin
 a:=app.active_assignment(p_actor);
 if a.id is null then raise exception 'Akun tidak memiliki penugasan aktif.'; end if;
 if p_action='CREATE' then
   select level into lvl from positions where id=a.position_id;
   r:=app.active_assignment((p_data->>'recipientId')::uuid);
   select level into rlv from positions where id=r.position_id;
   if lvl<=1 or r.id is null or rlv>=lvl or (p_data->>'recipientId')::uuid=p_actor or (lvl=2 and a.unit_id<>r.unit_id) then raise exception 'Pilih penerima dengan jabatan di bawah Anda sesuai kewenangan unit.'; end if;
   if length(trim(coalesce(p_data->>'subject','')))=0 or length(trim(coalesce(p_data->>'instruction','')))=0 then raise exception 'Perihal dan arahan wajib diisi.'; end if;
   src:=nullif(p_data->>'letterId','')::uuid;
   if src is not null and (not app.can_read_letter_for(p_actor,src) or not exists(select 1 from letters where id=src and status='NUMBERED')) then raise exception 'Surat acuan harus sudah bernomor dan dapat Anda akses.'; end if;
   insert into dispositions(giver_id,recipient_id,letter_id,subject,instruction,priority,due_date,status,requires_letter)
   values(p_actor,r.profile_id,src,trim(p_data->>'subject'),trim(p_data->>'instruction'),p_data->>'priority',nullif(p_data->>'dueDate','')::date,'NEW',coalesce((p_data->>'requiresLetter')::boolean,true)) returning * into d;
   target:=d.recipient_id;
 else
   select * into d from dispositions where id=p_id for update;
   if d.id is null or p_actor not in (d.giver_id,d.recipient_id) then raise exception 'Anda tidak berwenang mengakses disposisi ini.'; end if;
   if p_revision is distinct from d.revision then raise exception 'Disposisi telah berubah. Muat ulang halaman.'; end if;
   old_status:=d.status;
   if p_action='START' and p_actor=d.recipient_id and d.status in ('NEW','REVISION_REQUESTED') then
     update dispositions set status='IN_PROGRESS',read_at=coalesce(read_at,now()),revision=revision+1 where id=d.id returning * into d;
     target:=d.giver_id;
   elsif p_action='SUBMIT' and p_actor=d.recipient_id and d.status in ('NEW','IN_PROGRESS','REVISION_REQUESTED') then
     if nullif(trim(p_data->>'note'),'') is null then raise exception 'Catatan hasil pekerjaan wajib diisi.'; end if;
     update dispositions set status='IN_REVIEW',follow_up_note=trim(p_data->>'note'),submitted_at=now(),reviewed_at=null,revision=revision+1 where id=d.id returning * into d;
     target:=d.giver_id;
   elsif p_action in ('ACCEPT','RETURN') and p_actor=d.giver_id and d.status='IN_REVIEW' then
     if p_action='RETURN' and nullif(trim(p_data->>'note'),'') is null then raise exception 'Tuliskan bagian yang perlu diperbaiki.'; end if;
     update dispositions set status=case when p_action='ACCEPT' then 'DONE' else 'REVISION_REQUESTED' end,review_note=nullif(trim(p_data->>'note'),''),reviewed_at=now(),completed_at=case when p_action='ACCEPT' then now() else null end,revision=revision+1 where id=d.id returning * into d;
     target:=d.recipient_id;
   else raise exception 'Tindakan tidak sesuai tahap atau kewenangan Anda.';
   end if;
 end if;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,status_before,status_after,reason,metadata) values(p_actor,d.response_letter_id,'DISPOSITION_'||p_action,'dispositions',d.id::text,old_status,d.status,nullif(p_data->>'note',''),jsonb_build_object('source_letter_id',d.letter_id));
 insert into notifications(recipient_id,letter_id,disposition_id,event_type,title,is_read) values(target,d.response_letter_id,d.id,'DISPOSITION',case p_action when 'CREATE' then 'Disposisi baru diterima' when 'START' then 'Disposisi mulai dikerjakan' when 'SUBMIT' then 'Hasil disposisi menunggu pemeriksaan Anda' when 'RETURN' then 'Hasil disposisi perlu diperbaiki' else 'Hasil disposisi telah diterima' end,false);
 return d.id;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_letter(p_actor uuid, p_letter uuid, p_revision integer, p_external_confirmed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l letters;
begin
 select * into l from letters where id=p_letter for update;
 if l.id is null or l.creator_id<>p_actor or (app.active_assignment(p_actor)).id is null or l.status<>'NUMBERED' or l.revision is distinct from p_revision then raise exception 'Surat/versi tidak dapat difinalisasi oleh akun ini.'; end if;
 if l.finalized_at is not null then return; end if;
 if not exists(select 1 from letter_versions where id=l.current_version_id and version_kind in ('NUMBERED','SIGNED') and storage_path is not null and file_hash is not null) then raise exception 'La­ngkah penyimpanan dokumen bernomor belum selesai.'; end if;
 if l.required_signature_count>0 then
   if l.signature_mode='IN_APP' and (l.signature_status<>'UPLOADED' or (select count(*) from signature_requests where letter_id=l.id and status='UPLOADED')<>l.required_signature_count) then raise exception 'Seluruh TTD wajib belum selesai.'; end if;
   if l.signature_mode='EXTERNAL' and p_external_confirmed is distinct from true then raise exception 'Konfirmasi pengesahan di luar sistem wajib.'; end if;
 end if;
 update letters set finalized_at=now(),finalized_by=p_actor,revision=revision+1,updated_at=now() where id=l.id;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,version_id,metadata) values(p_actor,l.id,'FINALIZE','letters',l.id::text,l.current_version_id,jsonb_build_object('external_confirmation',p_external_confirmed));
end $function$

CREATE OR REPLACE FUNCTION public.issue_letter_number(p_letter_id uuid, p_actor uuid, p_idempotency_key text)
 RETURNS number_issuances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l letters; iss number_issuances; i integer; series number_series; t letter_types; pos uuid; floor_value integer; yr integer;
begin
 select * into l from letters where id=p_letter_id for update;
 if l.id is null or l.creator_id<>p_actor or (app.active_assignment(p_actor)).id is null then raise exception 'Hanya pembuat aktif dapat menerbitkan nomor.'; end if;
 if l.official_number is not null then select * into iss from number_issuances where letter_id=l.id; if iss.id is null or iss.status='CANCELLED' then raise exception 'Penerbitan lama perlu ditinjau pengelola.'; end if; return iss; end if;
 if l.current_version_id is null or l.status<>'READY_TO_ISSUE' or cardinality(l.signer_ids)<>l.required_signature_count then raise exception 'Surat belum siap diterbitkan.'; end if;
 if (select count(*) from approval_steps where letter_id=l.id and version_id=l.current_version_id and status='APPROVED')<>l.required_signature_count
 or exists(select 1 from unnest(l.signer_ids) x where not app.valid_signer(x)) then raise exception 'Persetujuan/kewenangan wajib belum lengkap.'; end if;
 select * into t from letter_types where id=l.letter_type_id;
 pos:=(app.active_assignment(l.signer_id)).position_id;
 select * into series from number_series where letter_type_id=t.id and status='ACTIVE' and
 ((t.series_basis='SIGNER_POSITION' and position_id=pos) or (t.series_basis='CREATOR_UNIT' and unit_id=l.creator_unit_id)) limit 1;
 if series.id is null then raise exception 'Tidak ada seri nomor aktif sesuai unit/jabatan.'; end if;
 yr:=extract(year from now() at time zone 'Asia/Jakarta');
 -- Nomor lama dibuat tanpa issuance. Counter tidak boleh menggunakan ulang nomor tersebut.
 select coalesce(max((regexp_match(x.official_number,'^([0-9]{3,})[0-9]{2}[-/]'))[1]::integer),0) into floor_value
 from letters x where x.letter_type_id=t.id and right(x.official_number,4)=yr::text and
 ((t.series_basis='CREATOR_UNIT' and x.creator_unit_id=l.creator_unit_id) or
 (t.series_basis='SIGNER_POSITION' and (app.active_assignment(x.signer_id)).position_id=pos));
 insert into number_counters(series_id,year,last_value) values(series.id,yr,floor_value)
 on conflict(series_id,year) do update set last_value=greatest(number_counters.last_value,excluded.last_value);
 iss:=issue_letter_number_core(p_letter_id,p_actor,p_idempotency_key);
 if l.signature_mode='IN_APP' then
   for i in 1..cardinality(l.signer_ids) loop
     insert into signature_requests(letter_id,numbered_version_id,signer_id,sign_order,signer_role,status)
     values(l.id,l.current_version_id,l.signer_ids[i],i,(select p.name from app.active_assignment(l.signer_ids[i]) a join positions p on p.id=a.position_id),case when i=1 then 'PENDING' else 'WAITING' end);
   end loop;
 end if;
 return iss;
end $function$

CREATE OR REPLACE FUNCTION public.issue_letter_number_core(p_letter_id uuid, p_actor uuid, p_idempotency_key text)
 RETURNS number_issuances
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_letter letters;
  v_type letter_types;
  v_series number_series;
  v_issuance number_issuances;
  v_year integer;
  v_seq integer;
  v_now timestamptz := now();
  v_unit text;
  v_pos text;
  v_number text;
  v_signer_pos uuid;
  v_sig_status text;
begin
  -- Kunci baris surat
  select * into v_letter from letters where id = p_letter_id for update;
  if not found then raise exception 'LETTER_NOT_FOUND' using errcode = 'P0002'; end if;

  -- Idempoten: bila sudah pernah diterbitkan untuk surat ini, kembalikan record yang sama
  select * into v_issuance from number_issuances where letter_id = p_letter_id;
  if found then
    if v_issuance.status = 'CANCELLED' then
      raise exception 'ISSUANCE_CANCELLED' using errcode = 'P0001';
    end if;
    return v_issuance;
  end if;

  -- Nomor hanya dapat diterbitkan bila berstatus READY_TO_ISSUE
  if v_letter.status <> 'READY_TO_ISSUE' then
    raise exception 'LETTER_NOT_READY: status %', v_letter.status using errcode = 'P0001';
  end if;

  select * into v_type from letter_types where id = v_letter.letter_type_id;

  if v_type.series_basis = 'SIGNER_POSITION' then
    select ua.position_id into v_signer_pos from user_assignments ua
      where ua.profile_id = v_letter.signer_id and ua.is_active order by ua.start_date desc nulls last limit 1;
    select * into v_series from number_series
      where letter_type_id = v_type.id and position_id = v_signer_pos and status = 'ACTIVE' limit 1;
  else
    select * into v_series from number_series
      where letter_type_id = v_type.id and unit_id = v_letter.creator_unit_id and status = 'ACTIVE' limit 1;
  end if;
  if v_series.id is null then raise exception 'NO_ACTIVE_SERIES' using errcode = 'P0001'; end if;

  -- Counter per seri dan tahun Asia/Jakarta
  v_year := extract(year from v_now at time zone 'Asia/Jakarta')::integer;
  insert into number_counters (series_id, year, last_value) values (v_series.id, v_year, 0)
    on conflict (series_id, year) do nothing;
  update number_counters set last_value = last_value + 1
    where series_id = v_series.id and year = v_year returning last_value into v_seq;

  select code into v_unit from organizational_units where id = v_letter.creator_unit_id;
  select p.code into v_pos from positions p where p.id = coalesce(v_signer_pos, v_series.position_id);
  v_number := build_official_number(v_series.pattern, v_seq, v_now, v_unit, v_pos, v_type.code);

  -- Hitung status tanda tangan
  v_sig_status := case
    when v_letter.required_signature_count = 0 then 'NOT_REQUIRED'
    when v_letter.signature_mode = 'IN_APP' then 'WAITING'
    when v_letter.signature_mode = 'EXTERNAL' then 'EXTERNAL'
    else 'NOT_REQUIRED' end;

  -- 1 Transaksi: Simpan number_issuances
  insert into number_issuances (
    letter_id, series_id, year, sequence_number, official_number, pattern_snapshot,
    status, idempotency_key, issued_by, issued_at, verified_at
  )
  values (
    p_letter_id, v_series.id, v_year, v_seq, v_number,
    jsonb_build_object('pattern', v_series.pattern, 'unit', v_unit, 'position', v_pos, 'type', v_type.code)::text,
    'ISSUED', p_idempotency_key, p_actor, v_now, v_now
  )
  returning * into v_issuance;

  -- 1 Transaksi: Update letters menjadi NUMBERED
  update letters set
    status = 'NUMBERED',
    official_number = v_number,
    issued_at = v_now,
    signature_status = v_sig_status,
    updated_at = v_now
  where id = v_letter.id;

  -- 1 Transaksi: Catat audit_logs
  insert into audit_logs (
    actor_id, letter_id, action, entity_type, entity_id, status_before, status_after, official_number
  )
  values (
    p_actor, p_letter_id, 'NUMBER_ISSUED', 'letters', v_letter.id::text, 'READY_TO_ISSUE', 'NUMBERED', v_number
  );

  return v_issuance;
end $function$

CREATE OR REPLACE FUNCTION public.letters_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.official_number is not null then raise exception 'surat bernomor tidak dapat dihapus' using errcode = 'P0001'; end if;
    return old;
  end if;
  if old.official_number is not null and (new.official_number is distinct from old.official_number or new.issued_at is distinct from old.issued_at) then
    raise exception 'nomor resmi dan tanggal terbit tidak dapat diubah' using errcode = 'P0001';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_final_letter()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if old.finalized_at is not null and (new.subject,new.letter_date,new.recipient_user_id,new.recipient_external_name,new.recipient_external_org,new.recipient_external_address,new.current_version_id,new.signer_ids,new.signature_areas,new.stamp_area,new.number_area,new.finalized_at) is distinct from (old.subject,old.letter_date,old.recipient_user_id,old.recipient_external_name,old.recipient_external_org,old.recipient_external_address,old.current_version_id,old.signer_ids,old.signature_areas,old.stamp_area,old.number_area,old.finalized_at) then raise exception 'Dokumen final terkunci.'; end if;
 if old.official_number is not null and (new.official_number,new.issued_at) is distinct from (old.official_number,old.issued_at) then raise exception 'Nomor resmi tidak dapat diubah.'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_final_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if exists(select 1 from letters where id=old.letter_id and finalized_at is not null) then raise exception 'Versi dokumen final terkunci.'; end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.record_numbered_document(p_actor uuid, p_letter uuid, p_previous_version uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l letters; v uuid; no integer; kind text;
begin
 select * into l from letters where id=p_letter for update;
 if l.creator_id is distinct from p_actor or l.status<>'NUMBERED' or l.finalized_at is not null then raise exception 'Tidak berwenang menyimpan salinan bernomor.'; end if;
 select version_kind into kind from letter_versions where id=l.current_version_id;
 if kind in ('NUMBERED','SIGNED') then return; end if;
 if l.current_version_id is distinct from p_previous_version or nullif(p_document->>'hash','') is null then raise exception 'Versi berubah.'; end if;
 select coalesce(max(version_no),0)+1 into no from letter_versions where letter_id=l.id;
 update letter_versions set is_current=false where letter_id=l.id and is_current;
 insert into letter_versions(letter_id,version_no,version_kind,storage_path,file_format,file_hash,created_by,is_current)
 values(l.id,no,'NUMBERED',p_document->>'path',p_document->>'format',p_document->>'hash',p_actor,true) returning id into v;
 update letters set current_version_id=v,revision=revision+1 where id=l.id;
 update signature_requests set numbered_version_id=v where letter_id=l.id and status in ('PENDING','WAITING');
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,version_id) values(p_actor,l.id,'NUMBERED_DOCUMENT_STORED','letters',l.id::text,v);
end $function$

CREATE OR REPLACE FUNCTION public.record_signature(p_actor uuid, p_request uuid, p_revision integer, p_previous_version uuid, p_document jsonb, p_method text, p_image_path text DEFAULT NULL::text, p_stamp_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l letters; s signature_requests; v uuid; no integer; remaining integer;
begin
 select * into s from signature_requests where id=p_request;
 select * into l from letters where id=s.letter_id for update;
 select * into s from signature_requests where id=p_request for update;
 if s.id is null or s.signer_id<>p_actor or not app.valid_signer(p_actor) or s.status<>'PENDING' or l.status<>'NUMBERED' or l.signature_mode<>'IN_APP' or l.finalized_at is not null then raise exception 'Anda bukan penandatangan aktif.'; end if;
 if not exists(select 1 from letter_versions where id=l.current_version_id and version_kind in ('NUMBERED','SIGNED')) then raise exception 'Dokumen bernomor belum tersimpan.'; end if;
 if l.revision is distinct from p_revision or l.current_version_id is distinct from p_previous_version then raise exception 'Dokumen telah berubah. Preview ulang sebelum tanda tangan.'; end if;
 if exists(select 1 from signature_requests where letter_id=l.id and sign_order<s.sign_order and status<>'UPLOADED') then raise exception 'Tanda tangan sebelumnya belum selesai.'; end if;
 if coalesce(p_method,'') not in ('IMAGE','WET_UPLOAD') or nullif(p_document->>'path','') is null or nullif(p_document->>'hash','') is null then raise exception 'Berkas hasil belum tersimpan.'; end if;
 if p_method='IMAGE' and nullif(p_image_path,'') is null then raise exception 'Gambar TTD wajib.'; end if;
 select coalesce(max(version_no),0)+1 into no from letter_versions where letter_id=l.id;
 update letter_versions set is_current=false where letter_id=l.id and is_current;
 insert into letter_versions(letter_id,version_no,version_kind,storage_path,file_format,file_hash,created_by,is_current)
 values(l.id,no,'SIGNED',p_document->>'path',p_document->>'format',p_document->>'hash',p_actor,true) returning id into v;
 update signature_requests set status='UPLOADED',signed_version_id=v,uploaded_at=now(),stamp_included=p_stamp_path is not null,signature_image_path=p_image_path,stamp_image_path=p_stamp_path,method=p_method where id=s.id;
 select count(*) into remaining from signature_requests where letter_id=l.id and status in ('PENDING','WAITING');
 update signature_requests set status='PENDING' where id=(select id from signature_requests where letter_id=l.id and status='WAITING' order by sign_order limit 1);
 update letters set current_version_id=v,revision=revision+1,signature_status=case when remaining=0 then 'UPLOADED' else 'WAITING' end,updated_at=now() where id=l.id;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,version_id,metadata) values(p_actor,l.id,'SIGNATURE_APPLIED','signature_requests',s.id::text,v,jsonb_build_object('method',p_method,'hash',p_document->>'hash','order',s.sign_order));
 if p_stamp_path is not null then insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,version_id) values(p_actor,l.id,'STAMP_APPLIED','letters',l.id::text,v); end if;
 insert into notifications(recipient_id,letter_id,event_type,title,is_read) values(l.creator_id,l.id,'SIGNATURE_APPLIED','Dokumen bertanda tangan telah tersimpan.',false);
 return v;
end $function$

CREATE OR REPLACE FUNCTION public.review_letter(p_actor uuid, p_letter uuid, p_action text, p_revision integer, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare l letters; s approval_steps; nxt approval_steps; i integer; c integer; dest text;
begin
 select * into l from letters where id=p_letter for update;
 if l.id is null or (app.active_assignment(p_actor)).id is null then raise exception 'Akun/surat tidak valid.'; end if;
 if l.finalized_at is not null or l.revision is distinct from p_revision then raise exception 'Versi surat berubah atau telah final.'; end if;
 if p_action='PREVIEW' then
   if l.creator_id<>p_actor or l.status not in ('DRAFT','REVISION_REQUESTED') then raise exception 'Preview draft hanya oleh pembuat.'; end if;
   update letters set previewed_revision=revision where id=l.id; return l.status;
 elsif p_action='SUBMIT' then
   if l.creator_id<>p_actor or l.status not in ('DRAFT','REVISION_REQUESTED') or l.current_version_id is null or l.previewed_revision is distinct from l.revision then raise exception 'Simpan dan preview draft terkini sebelum mengajukan.'; end if;
   if exists(select 1 from unnest(l.signer_ids) x where not app.valid_signer(x)) then raise exception 'Kewenangan penandatangan berubah.'; end if;
   if exists(select 1 from letter_types where id=l.letter_type_id and required_attachment) and not exists(select 1 from letter_attachments where letter_id=l.id) then raise exception 'Lampiran bukti wajib sebelum pengajuan.'; end if;
   select coalesce(max(cycle),0)+1 into c from approval_steps where letter_id=l.id;
   update approval_steps set status='SUPERSEDED' where letter_id=l.id and status in ('PENDING','WAITING');
   for i in 1..cardinality(l.signer_ids) loop
     insert into approval_steps(letter_id,cycle,step_order,approver_id,step_source,status,version_id)
     values(l.id,c,i,l.signer_ids[i],case when cardinality(l.signer_ids)=2 then case when i=1 then 'BILLING_SUBMITTER' else 'BILLING_APPROVER' end else 'SIGNER_CONFIRMATION' end,case when i=1 then 'PENDING' else 'WAITING' end,l.current_version_id);
   end loop;
   dest:=case when cardinality(l.signer_ids)=0 then 'READY_TO_ISSUE' else 'IN_REVIEW' end;
 else
   if l.status<>'IN_REVIEW' then raise exception 'Surat tidak dalam persetujuan.'; end if;
   select * into s from approval_steps where letter_id=l.id and approver_id=p_actor and status='PENDING' order by cycle desc limit 1 for update;
   if s.id is null or s.version_id is distinct from l.current_version_id or not app.valid_signer(p_actor) then raise exception 'Bukan penyetuju aktif pada versi ini.'; end if;
   if p_action not in ('APPROVE','REJECT','REQUEST_REVISION') then raise exception 'Aksi tidak valid.'; end if;
   if p_action<>'APPROVE' and nullif(trim(p_note),'') is null then raise exception 'Alasan wajib diisi.'; end if;
   update approval_steps set status=case p_action when 'APPROVE' then 'APPROVED' when 'REJECT' then 'REJECTED' else 'REVISION_REQUESTED' end,decided_at=now(),decision_note=p_note where id=s.id;
   if p_action='APPROVE' then
     select * into nxt from approval_steps where letter_id=l.id and cycle=s.cycle and step_order>s.step_order and status='WAITING' order by step_order limit 1;
     if nxt.id is not null then update approval_steps set status='PENDING' where id=nxt.id; dest:='IN_REVIEW'; else dest:='READY_TO_ISSUE'; end if;
   else
     dest:=case p_action when 'REJECT' then 'REJECTED' else 'REVISION_REQUESTED' end;
     update approval_steps set status='SUPERSEDED' where letter_id=l.id and cycle=s.cycle and status in ('PENDING','WAITING');
   end if;
 end if;
 update letters set status=dest,status_reason=p_note,updated_at=now() where id=l.id;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,status_before,status_after,version_id,reason)
 values(p_actor,l.id,p_action,'letters',l.id::text,l.status,dest,l.current_version_id,p_note);
 insert into notifications(recipient_id,letter_id,event_type,title,is_read) values(l.creator_id,l.id,p_action,'Status surat diperbarui: '||dest,false);
 insert into notifications(recipient_id,letter_id,event_type,title,is_read)
 select approver_id,l.id,'APPROVAL_REQUEST','Surat menunggu persetujuan Anda.',false from approval_steps where letter_id=l.id and status='PENDING';
 return dest;
end $function$

CREATE OR REPLACE FUNCTION public.save_letter_draft(p_actor uuid, p_data jsonb, p_document jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare d dispositions; v uuid; did uuid; old_id uuid;
begin
 did:=nullif(p_data->>'dispositionId','')::uuid;
 -- Edit surat yang sudah terhubung juga tidak boleh melewati tahap pemeriksaan.
 if did is null and nullif(p_data->>'id','') is not null then select id into did from dispositions where response_letter_id=(p_data->>'id')::uuid; end if;
 if did is not null then
   select * into d from dispositions where id=did for update;
   if d.id is null or d.recipient_id<>p_actor or d.status not in ('NEW','IN_PROGRESS','REVISION_REQUESTED') then raise exception 'Surat tindak lanjut hanya dapat dikerjakan oleh penerima sebelum dikirim untuk pemeriksaan.'; end if;
   if d.response_letter_id is not null and nullif(p_data->>'id','') is null and exists(select 1 from letters where id=d.response_letter_id and finalized_at is null and status not in ('REJECTED','CANCELLED')) then raise exception 'Lanjutkan surat tindak lanjut yang sudah dibuat.'; end if;
   if nullif(p_data->>'id','') is not null and d.response_letter_id is distinct from (p_data->>'id')::uuid then raise exception 'Surat tidak sesuai disposisi.'; end if;
 end if;
 v:=save_letter_draft_core(p_actor,p_data,p_document);
 if did is not null then
   old_id:=d.response_letter_id;
   update dispositions set response_letter_id=v,submitted_at=case when response_letter_id is distinct from v then null else submitted_at end,status=case when status='NEW' then 'IN_PROGRESS' else status end,revision=revision+1 where id=did;
   insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,metadata) values(p_actor,v,'DISPOSITION_LETTER_SAVED','dispositions',did::text,jsonb_build_object('previous_letter_id',old_id));
 end if;
 return v;
end $function$

CREATE OR REPLACE FUNCTION public.save_letter_draft_core(p_actor uuid, p_data jsonb, p_document jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
 l letters; t letter_types; a user_assignments; s uuid; n integer; v uuid; no integer;
 d date; ids uuid[]; b jsonb; old_date date; new_id uuid; expected integer; bank uuid;
begin
 a:=app.active_assignment(p_actor);
 if a.id is null then raise exception 'Akun tidak memiliki penugasan aktif.'; end if;
 select * into t from letter_types where code=p_data->>'letterTypeCode' and is_active;
 if t.id is null or nullif(trim(p_data->>'subject'),'') is null then raise exception 'Jenis surat dan perihal wajib diisi.'; end if;
 d:=(p_data->>'letterDate')::date;
 if d is null then raise exception 'Tanggal surat wajib diisi.'; end if;
 if nullif(p_data->>'id','') is not null then
   select * into l from letters where id=(p_data->>'id')::uuid for update;
   if l.id is null or l.creator_id<>p_actor or l.status not in ('DRAFT','REVISION_REQUESTED') or l.finalized_at is not null then raise exception 'Draft tidak dapat diubah oleh akun ini.'; end if;
   expected:=(p_data->>'revision')::integer;
   if expected is distinct from l.revision then raise exception 'Draft telah berubah. Muat ulang sebelum menyimpan.'; end if;
   if l.letter_type_id<>t.id then raise exception 'Jenis surat tidak dapat diganti setelah draft dibuat.'; end if;
   old_date:=l.letter_date;
 end if;
 if d < (now() at time zone 'Asia/Jakarta')::date and (l.id is null or d is distinct from old_date) then
   if not app.can_backdate(p_actor) or nullif(trim(p_data->>'dateReason'),'') is null then raise exception 'Tanggal mundur memerlukan kewenangan GM/SM/Direktur dan alasan.'; end if;
 end if;
 select coalesce(array_agg(x::uuid),'{}') into ids from jsonb_array_elements_text(coalesce(p_data->'signerIds','[]')) x;
 n:=cardinality(ids);
 if n<>(select count(distinct x) from unnest(ids) x) then raise exception 'Penandatangan harus berbeda.'; end if;
 foreach s in array ids loop
   if not app.valid_signer(s) then raise exception 'Penandatangan harus pejabat SM/Direktur aktif yang berwenang.'; end if;
 end loop;
 if t.category='INTERNAL' then
   if n>1 or not exists(select 1 from profiles where id=(p_data->>'recipientUserId')::uuid and is_active) then raise exception 'Pilih penerima internal aktif; maksimal satu TTD formal.'; end if;
 else
   if nullif(trim(p_data->>'recipientName'),'') is null or nullif(trim(p_data->>'recipientOrg'),'') is null or nullif(trim(p_data->>'recipientAddress'),'') is null then raise exception 'Nama, instansi, dan alamat penerima eksternal wajib diisi.'; end if;
   if t.category='EXTERNAL' and n<>1 then raise exception 'Surat eksternal wajib satu penandatangan.'; end if;
 end if;
 if t.category='BILLING' then
   if t.creator_unit_id is distinct from a.unit_id or n<>2 then raise exception 'Tagihan khusus Finance dan wajib dua penandatangan.'; end if;
   if not exists(select 1 from app.active_assignment(ids[1]) x join positions p on p.id=x.position_id join organizational_units u on u.id=x.unit_id where p.code='SM')
   or not exists(select 1 from app.active_assignment(ids[2]) x join positions p on p.id=x.position_id where p.code='DIR') then raise exception 'Urutan tagihan: Senior Manager lalu Direktur.'; end if;
   b:=p_data->'billing';
   bank:=nullif(b->>'bankId','')::uuid;
   if bank is null and nullif(trim(b->>'bankName'),'') is not null then
     select id into bank from master_bank where lower(name)=lower(trim(b->>'bankName')) and is_active limit 1;
     if bank is null then insert into master_bank(name,is_active) values(trim(b->>'bankName'),true) returning id into bank; end if;
   end if;
   if b is null or coalesce(jsonb_array_length(b->'items'),0)<2 or nullif(b->>'accountNumber','') is null or nullif(b->>'accountHolder','') is null
   or not exists(select 1 from master_bank where id=bank and is_active)
   or exists(select 1 from jsonb_array_elements(b->'items') i where (i->>'amount')::numeric<=0 or nullif(trim(i->>'description'),'') is null) then raise exception 'Rincian tagihan dan rekening tidak lengkap.'; end if;
 end if;
 if coalesce(p_data->>'signatureMode','') not in ('IN_APP','EXTERNAL') then raise exception 'Pilih jalur TTD.'; end if;
 if nullif(p_document->>'path','') is null or nullif(p_document->>'hash','') is null or p_document->>'format' not in ('PDF','DOCX') then raise exception 'Dokumen belum tersimpan di Supabase.'; end if;
 if coalesce((select sum((i->>'size')::bigint) from jsonb_array_elements(coalesce(p_document->'attachments','[]')) i),0)+coalesce((select sum(size_bytes) from letter_attachments where letter_id=l.id),0)>26214400 then raise exception 'Total lampiran maksimal 25 MB.'; end if;
 if l.id is null then
   insert into letters(letter_type_id,source,subject,creator_id,creator_unit_id,recipient_type,status,required_signature_count)
   values(t.id,p_data->>'source',p_data->>'subject',p_actor,a.unit_id,case when t.category='INTERNAL' then 'INTERNAL_USER' else 'EXTERNAL' end,'DRAFT',n) returning * into l;
 end if;
 update letters set subject=trim(p_data->>'subject'), letter_date=d, date_change_reason=p_data->>'dateReason',
 recipient_user_id=case when t.category='INTERNAL' then (p_data->>'recipientUserId')::uuid else null end,
 recipient_external_name=case when t.category<>'INTERNAL' then p_data->>'recipientName' else null end,
 recipient_external_org=case when t.category<>'INTERNAL' then p_data->>'recipientOrg' else null end,
 recipient_external_address=case when t.category<>'INTERNAL' then p_data->>'recipientAddress' else null end,
 signer_id=ids[1], signer_ids=ids, required_signature_count=n, signature_mode=p_data->>'signatureMode',
 signature_status='NOT_STARTED',signature_areas=coalesce(p_data->'areas','[]'),stamp_area=nullif(p_data->'stampArea','null'),number_area=nullif(p_data->'numberArea','null'),
 revision=revision+1, previewed_revision=null, updated_at=now() where id=l.id;
 select coalesce(max(version_no),0)+1 into no from letter_versions where letter_id=l.id;
 update letter_versions set is_current=false where letter_id=l.id and is_current;
 insert into letter_versions(letter_id,version_no,version_kind,storage_path,file_format,file_hash,content_html,content_format,created_by,is_current,original_name)
 values(l.id,no,'DRAFT',p_document->>'path',p_document->>'format',p_document->>'hash',p_data->>'content',coalesce(p_data->>'contentFormat','TEXT'),p_actor,true,p_document->>'name') returning id into v;
 update letters set current_version_id=v where id=l.id;
 insert into letter_attachments(letter_id,file_name,storage_path,mime_type,size_bytes,uploaded_by)
 select l.id,i->>'name',i->>'path',i->>'mime',(i->>'size')::bigint,p_actor from jsonb_array_elements(coalesce(p_document->'attachments','[]')) i;
 if b is not null then
   insert into billing_details(letter_id,bank_id,payee_name,account_number,total_amount,total_in_words)
   values(l.id,bank,b->>'accountHolder',b->>'accountNumber',(select sum((i->>'amount')::numeric) from jsonb_array_elements(b->'items') i),b->>'totalInWords')
   on conflict(letter_id) do update set bank_id=excluded.bank_id,payee_name=excluded.payee_name,account_number=excluded.account_number,total_amount=excluded.total_amount,total_in_words=excluded.total_in_words;
   delete from billing_items where letter_id=l.id;
   insert into billing_items(letter_id,line_no,description,amount) select l.id,ord,i->>'description',(i->>'amount')::numeric from jsonb_array_elements(b->'items') with ordinality as j(i,ord);
 end if;
 insert into audit_logs(actor_id,letter_id,action,entity_type,entity_id,version_id,metadata)
 values(p_actor,l.id,case when old_date is distinct from d then 'LETTER_DATE_SET' else 'SAVE_DRAFT' end,'letters',l.id::text,v,jsonb_build_object('date_before',old_date,'date_after',d,'reason',p_data->>'dateReason','revision',l.revision+1));
 return l.id;
end $function$
